from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine
        self.books = set()          # all known book ids
        self.borrowed = {}          # book_id -> (user, borrow_day)
        self.fines = {}             # user -> outstanding fine

    def add_book(self, book_id: str) -> None:
        self.books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self.books:
            raise ValueError("Unknown book")
        if book_id in self.borrowed:
            raise ValueError("Book already borrowed")
        if self.fines.get(user, 0) > 0:
            # at most one book at a time while fines are unpaid
            held = any(u == user for u, _ in self.borrowed.values())
            if held:
                raise ValueError("User with unpaid fines may hold only one book")
        self.borrowed[book_id] = (user, day)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        if book_id not in self.borrowed:
            raise ValueError("Book is not borrowed")
        holder, borrow_day = self.borrowed[book_id]
        if holder != user:
            raise ValueError("Book was borrowed by a different user")

        due = borrow_day + timedelta(days=self.loan_days)
        fine = 0.0
        if day > due:
            cur = due + timedelta(days=1)
            late_days = 0
            while cur <= day:
                if cur.weekday() < 5:  # Monday..Friday
                    late_days += 1
                cur += timedelta(days=1)
            fine = late_days * self.daily_fine

        if fine > 0:
            self.fines[user] = self.fines.get(user, 0.0) + fine

        del self.borrowed[book_id]
        return fine

    def unpaid_fines(self, user: str) -> float:
        return self.fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        self.fines.pop(user, None)
